55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        LocalDate registrationDate = BusinessDay.adjust(
109	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
110	        owner.setRegistrationDate(registrationDate);
111	        Collection<Owner> owners = this.clinicService.findAllOwners().stream().filter(existing -> !existing.isDeleted()).toList();
112	        if (owners.stream().filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() >= 100) {
113	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
114	        }
115	        if (owners.stream().anyMatch(existing -> existing.getIdentityKey().equals(owner.getIdentityKey()))
116	                || owners.stream().filter(existing -> existing.getCity().equalsIgnoreCase(owner.getCity())).count() >= 50) {
117	            return new ResponseEntity<>(HttpStatus.CONFLICT);
118	        }
119	        owner.setNamesakeCount((int) owners.stream()
120	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(owner.getFirstName())
121	                && existing.getLastName().equalsIgnoreCase(owner.getLastName()))
122	            .count());
123	        owner.setHouseholdMemberCount(1 + (int) owners.stream().filter(existing -> sameHousehold(existing, owner)).count());
124	        owner.setCustomerCode(CustomerCode.of(owner, owners));
125	        owner.setPossibleDuplicate(false);
126	        owner.setPossibleDuplicateOf(null);
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        int householdMax = owners.stream().filter(existing -> sameHousehold(existing, owner))
130	            .mapToInt(existing -> MembershipLevel.of(MembershipLevel.points(existing.getNamesakeCount(),
131	                existing.getEmail(), existing.getHouseholdMemberCount(), existing.getRegistrationDate())))
132	            .max().orElse(-1);
133	        if (householdMax >= 0 && ownerDto.getMembershipLevel() > householdMax + 1) {
134	            ownerDto.setMembershipLevel(householdMax + 1);
135	        }
136	        ownerDto.setBulkSignupWarning(owners.stream()
137	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() > 80);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
141	    }
142	
143	    /** Two owners share a household when they resolve to the same {@link Owner#getHouseholdId()}
144	     *  (matching last name and postcode). */
145	    private static boolean sameHousehold(Owner a, Owner b) {
146	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
152	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
153	        if (currentOwner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        currentOwner.setAddress(ownerFieldsDto.getAddress());
157	        currentOwner.setCity(ownerFieldsDto.getCity());
158	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
159	        currentOwner.setLastName(ownerFieldsDto.getLastName());
160	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
161	        this.clinicService.saveOwner(currentOwner);
162	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Transactional
167	    @Override
168	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        owner.setDeleted(true);
174	        this.clinicService.saveOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        HttpHeaders headers = new HttpHeaders();
186	        Pet pet = petMapper.toPet(petFieldsDto);
187	        owner.setId(ownerId);
188	        pet.setOwner(owner);
189	        pet.getType().setName(null);
190	        this.clinicService.savePet(pet);
191	        PetDto petDto = petMapper.toPetDto(pet);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
193	            .buildAndExpand(pet.getId()).toUri());
194	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner != null) {
202	            Pet currentPet = this.clinicService.findPetById(petId);
203	            if (currentPet != null) {
204	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
205	                currentPet.setName(petFieldsDto.getName());
206	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
207	                this.clinicService.savePet(currentPet);
208	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
209	            }
210	        }
211	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
217	        HttpHeaders headers = new HttpHeaders();
218	        Visit visit = visitMapper.toVisit(visitFieldsDto);
219	        Pet pet = new Pet();
220	        pet.setId(petId);
221	        visit.setPet(pet);
222	        this.clinicService.saveVisit(visit);
223	        VisitDto visitDto = visitMapper.toVisitDto(visit);
224	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
225	            .buildAndExpand(visit.getId()).toUri());
226	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
227	    }
228	
229	
230	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
231	    @Override
232	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
233	        Owner owner = this.clinicService.findOwnerById(ownerId);
234	        if (owner != null) {
235	            Pet pet = owner.getPet(petId);
236	            if (pet != null) {
237	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
238	            }
239	        }
240	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	    }
242	}
