8	/**
9	 * Rejects an email whose domain is a known disposable-mail provider. A blank or absent email,
10	 * or one with no domain part, is left to the field-level format constraint and accepted here.
11	 */
12	public class NonDisposableEmailValidator implements ConstraintValidator<NonDisposableEmail, String> {
13	
14	    private static final Set<String> BLOCKED = Set.of(
15	        "mailinator.com", "tempmail.com", "guerrillamail.com");
